ss=&quot;pagelink&quot; href=&quot;Distraction-T&#233;l&#233;pathique.html&quot; title=&quot;Distraction t&#233;l&#233;pathique&quot;&gt;Distraction t&#233;l&#233;pathique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Cha&quot;&gt;Cha&lt;/a&gt; 15, &lt;a class=&quot;pagelink&quot; href=&quot;Homme-Serpent.html&quot; title=&quot;Homme-serpent&quot;&gt;homme-serpent&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Concentre la t&#233;l&#233;pathie pour rendre une cr&#233;ature plus vuln&#233;rable aux effets mentaux&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Magie-Inn&#233;e.html&quot; title=&quot;Magie inn&#233;e&quot;&gt;Magie inn&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Lanceur de sorts profanes, &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 4, &lt;a class=&quot;pagelink&quot; href=&quot;Homme-Serpent.html&quot; title=&quot;Homme-serpent&quot;&gt;homme-serpent&lt;/a&gt;&lt;/td&gt;&lt;td&gt;D&#233;pense des sorts profanes pr&#233;par&#233;s pour r&#233;utiliser des pouvoirs magiques&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
